class KimiKDAModel(nn.Module):
    """Kimi KDA model with fused Triton kernels."""

    def __init__(self, config, ...):
        super().__init__()
        self.o_norm = RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.num_heads = config.num_attention_heads
        self.head_dim = config.hidden_size // self.num_heads
        # ...

    def forward(self, hidden_states, ...):
        # ... attention computation ...
        core_attn_out = self._compute_attention(...)
        output_gate = self._compute_gate(...)
        return self._apply_output_norm_gate(core_attn_out, output_gate)

    def _apply_output_norm_gate(
        self,
        core_attn_out: torch.Tensor,
        output_gate: torch.Tensor,
    ) -> torch.Tensor:
        if apply_kda_rms_norm_sigmoid_gate is not None:
            return apply_kda_rms_norm_sigmoid_gate(
                core_attn_out,
                output_gate,
                self.o_norm.weight,
                self.o_norm.eps,
            )
        # fallback: 使用标准 PyTorch RMSNorm
        return self.o_norm(core_attn_out, output_gate)
